/**
 * @file bios_oracle.h
 * @brief The oracle's answers to the cases of bios_cases.h, as digests (generated by
 * the lane's oracle runner from the DS test ROM's logs; see test_bios.c for the folding).
 */
#ifndef RELIFT_NDS_BIOS_ORACLE_H
#define RELIFT_NDS_BIOS_ORACLE_H

/** @brief One digest: group, CPU (9 or 7), count of cases folded, FNV-1a digest. */
typedef struct bios_oracle {
    const char *group;
    unsigned cpu, cases;
    uint32_t digest;
} bios_oracle;

/** @brief The digests. */
static const bios_oracle bios_oracle_digests[] = {
    {"sqrt", 9, 290, 0x21844BCCu},
    {"sqrt", 7, 290, 0x21844BCCu},
    {"cpuset", 9, 300, 0xDBF40F19u},
    {"cpuset", 7, 300, 0xDBF40F19u},
    {"fastset", 9, 300, 0x6F5111ACu},
    {"fastset", 7, 300, 0x6F5111ACu},
    {"crc16", 9, 120, 0x2C519AFDu},
    {"crc16", 7, 120, 0x2C519AFDu},
    {"bitunpack", 9, 300, 0xEC70BD67u},
    {"bitunpack", 7, 300, 0xEC70BD67u},
    {"lz8", 9, 200, 0xD7C31342u},
    {"lz8", 7, 200, 0xD7C31342u},
    {"lzcb", 9, 108, 0x68636766u},
    {"lzcb", 7, 108, 0x68636766u},
    {"rl8", 9, 150, 0x3773B9F5u},
    {"rl8", 7, 150, 0x3773B9F5u},
    {"rlcb", 9, 90, 0xDD4BA736u},
    {"rlcb", 7, 90, 0xDD4BA736u},
    {"diff8", 9, 59, 0xB98932D4u},
    {"diff16", 9, 59, 0xE44A3F1Cu},
    {"sine", 7, 64, 0xA1723FA5u},
    {"pitch", 7, 768, 0xAEBB4A90u},
    {"vol", 7, 724, 0xC89734AFu},
    {"dbg", 9, 1, 0x4B95F515u},
    {"dbg", 7, 1, 0x4B95F515u},
    {"div", 9, 266, 0x438529EEu},
};

/** @brief Cases the oracle's open BIOS never finishes (skipped on both sides): group, CPU, case. */
typedef struct bios_skip {
    const char *group;
    unsigned cpu, index;
} bios_skip;

/** @brief The skipped cases. */
static const bios_skip bios_oracle_skips[] = {
    {"diff8", 9, 0},
    {"diff16", 9, 0},
    {"div", 9, 228},
    {"div", 9, 229},
    {"div", 9, 233},
    {"div", 9, 235},
    {"div", 9, 237},
    {"div", 9, 239},
    {"div", 9, 241},
    {"div", 9, 242},
    {"div", 9, 246},
    {"", 0, 0},
};

#endif
